import json
rows = json.load(open("customers.json"))

def line(customer, plan):
    return f"{customer}: {plan}"

for row in rows:
    print(line(row["name"]))

import json
data = json.load(open("order.json"))
total = 0

def add_item(name, qty):
    if qty > 0:
        total = total + qty
    return name, total

for it in data["items"]:
    name, total = add_item(it["name"], it["qty"])
    print(name, total)

import json
n = json.load(open("cfg.json"))["start"]

def countdown(x):
    return x + countdown(x - 1)

print("RESULT:", countdown(n))
